export const ERASED_CUSTOMER: Record<string, unknown> = { erased: true };

const PERSONAL_DATA_KEYS = new Set([
  'email', 'emailaddress', 'customeremail', 'billingemail', 'destination', 'recipient',
  'name', 'customername', 'billingname', 'displayname', 'fullname', 'firstname', 'lastname',
  'phone', 'phonenumber', 'customerphone', 'mobile',
  'externalreference', 'externalid',
  'address', 'billingaddress', 'shippingaddress', 'line1', 'line2', 'street',
