  'subject', 'body', 'textbody', 'htmlbody', 'message', 'note', 'notes', 'description', 'value',
  'customer', 'customersnapshot', 'billingsnapshot', 'contact', 'contacts', 'metadata', 'record',
]);

function normalize(key: string): string {
  return key.toLowerCase().replaceAll(/[^a-z0-9]/g, '');
}

/** Reports whether an event or job payload key may carry customer personal data. */
export function isPersonalDataKey(key: string): boolean {
  return PERSONAL_DATA_KEYS.has(normalize(key));
}

/**
 * Removes personal data from a stored payload while keeping the identifiers, amounts and
 * statuses that retained records, reconciliation and replay protection depend on.
 */
export function scrubPersonalData(value: unknown): unknown {
  if (Array.isArray(value)) return value.map((item) => scrubPersonalData(item));
  if (value === null || typeof value !== 'object') return value;
  const scrubbed: Record<string, unknown> = {};
  for (const [key, item] of Object.entries(value as Record<string, unknown>)) {
    if (isPersonalDataKey(key)) continue;
    scrubbed[key] = scrubPersonalData(item);
  }
  return scrubbed;
}

/** Replaces the customer profile embedded in a retained financial document. */
export function scrubStoredDocument(document: unknown): unknown {
  if (document === null || typeof document !== 'object' || Array.isArray(document)) return document;
  const source = document as Record<string, unknown>;
  const scrubbed: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(source)) {
    scrubbed[key] = isPersonalDataKey(key) ? undefined : value;
    if (scrubbed[key] === undefined) delete scrubbed[key];
  }
  if ('customer' in source) scrubbed.customer = ERASED_CUSTOMER;
  return scrubbed;
}
