import { pool } from '../../database/src/pool.js';

/**
 * The tombstone is written before any data is removed, so delayed work observes an erased
 * customer for the whole workflow and not only after it completes.
 */
export async function markCustomerErased(
  client: PoolClient,
  merchantId: string,
  customerId: string,
  requestId: string,
): Promise<void> {
  await client.query(
    `INSERT INTO privacy.erased_customers(merchant_id,customer_id,request_id)
     VALUES($1,$2,$3) ON CONFLICT(merchant_id,customer_id) DO NOTHING`,
    [merchantId, customerId, requestId],
  );
}

export async function isCustomerErased(merchantId: string, customerId: string): Promise<boolean> {
  const result = await pool.query(
    `SELECT 1 FROM privacy.erased_customers WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  return Boolean(result.rowCount);
}

export async function isCustomerErasedIn(
  client: PoolClient,
  merchantId: string,
  customerId: string,
): Promise<boolean> {
  const result = await client.query(
    `SELECT 1 FROM privacy.erased_customers WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  return Boolean(result.rowCount);
}
