{"command":"create","path":"/workspace/source/packages/privacy/src/erasure-targets.ts","file_text":"import type { PoolClient } from 'pg';

export interface ErasureTarget {
  merchantId: string;
  customerId: string;
  requestId: string;
}

export interface RelatedRecords {
  paymentIds: string[];
  refundIds: string[];
  invoiceIds: string[];
  /** Aggregate identifiers whose events and documents describe this customer. */
  aggregateIds: string[];
}

/**
 * Financial records are retained, so their identifiers stay available for every step and let the
 * workflow find the payloads, documents and projections derived from them.
 */
export async function relatedRecords(client: PoolClient, target: ErasureTarget): Promise<RelatedRecords> {
  const payments = await client.query<{ id: string }>(
    `SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2`,
    [target.merchantId, target.customerId],
  );
  const paymentIds = payments.rows.map((row) => row.id);
  const refunds = await client.query<{ id: string }>(
    `SELECT id FROM payments.refunds WHERE merchant_id=$1 AND payment_intent_id=ANY($2::uuid[])`,
    [target.merchantId, paymentIds],
  );
  const invoices = await client.query<{ id: string }>(
    `SELECT id FROM payments.invoices WHERE merchant_id=$1 AND customer_id=$2`,
    [target.merchantId, target.customerId],
  );
  const refundIds = refunds.rows.map((row) => row.id);
  const invoiceIds = invoices.rows.map((row) => row.id);
  return {
    paymentIds,
    refundIds,
    invoiceIds,
    aggregateIds: [target.customerId, ...paymentIds, ...refundIds, ...invoiceIds],
  };
}

/**
 * Collects every address the platform has used to contact the customer. Addresses shared with
 * another customer or merchant are left alone so deletion never touches someone else's data.
 */
export async function contactAddresses(client: PoolClient, target: ErasureTarget, paymentIds: string[]): Promise<string[]> {
  const result = await client.query<{ address: string }>(
    `SELECT DISTINCT address FROM (
       SELECT email address FROM customers.customers WHERE merchant_id=$1 AND id=$2
       UNION SELECT value FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2 AND kind='email'
       UNION SELECT destination FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2
       UNION SELECT destination FROM operations.email_deliveries WHERE merchant_id=$1 AND customer_id=$2
       UNION SELECT customer_email FROM payments.refunds WHERE merchant_id=$1 AND payment_intent_id=ANY($3::uuid[])
       UNION SELECT customer_snapshot->>'email' FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2
       UNION SELECT billing_snapshot->>'email' FROM payments.invoices WHERE merchant_id=$1 AND customer_id=$2
     ) addresses WHERE address IS NOT NULL AND address<>''`,
    [target.merchantId, target.customerId, paymentIds],
  );
  const addresses: string[] = [];
  for (const { address } of result.rows) {
    if (!await isSharedAddress(client, target, address)) addresses.push(address);
  }
  return addresses;
}

async function isSharedAddress(client: PoolClient, target: ErasureTarget, address: string): Promise<boolean> {
  const result = await client.query(
    `SELECT 1 FROM customers.customers
     WHERE email=$1 AND NOT (merchant_id=$2 AND id=$3)
     UNION ALL
     SELECT 1 FROM operations.email_deliveries
     WHERE destination=$1 AND NOT (merchant_id=$2 AND (customer_id=$3 OR customer_id IS NULL))
     LIMIT 1`,
    [address, target.merchantId, target.customerId],
  );
  return Boolean(result.rowCount);
}

/** Identifying values used to recognise the customer inside opaque uploaded artifacts. */
export async function customerIdentifiers(client: PoolClient, target: ErasureTarget): Promise<string[]> {
  const result = await client.query<{ email: string; external_reference: string }>(
    `SELECT email,external_reference FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
    [target.merchantId, target.customerId],
  );
  const row = result.rows[0];
  return [target.customerId, ...(row ? [row.email, row.external_reference] : [])];
}
