{"command":"create","path":"/workspace/source/packages/privacy/src/database-erasure.ts","file_text":"import type { PoolClient } from 'pg';
import { markCustomerErased } from './erased-customers.js';
import { ERASED_CUSTOMER, scrubPersonalData } from './personal-data.js';
import { customerIdentifiers, type ErasureTarget, type RelatedRecords } from './erasure-targets.js';

/**
 * Stops the platform from producing new copies of the customer's personal data and removes the
 * payloads that queued work would otherwise publish, deliver or render.
 */
export async function quarantineCustomer(
  client: PoolClient,
  target: ErasureTarget,
  related: RelatedRecords,
): Promise<void> {
  await markCustomerErased(client, target.merchantId, target.customerId, target.requestId);
  await client.query(
    `DELETE FROM operations.notifications
     WHERE merchant_id=$1 AND delivery_id IN (
       SELECT id FROM operations.email_deliveries
       WHERE merchant_id=$1 AND customer_id=$2 AND status<>'delivered'
     )`,
    [target.merchantId, target.customerId],
  );
  await client.query(
    `DELETE FROM operations.email_deliveries
     WHERE merchant_id=$1 AND customer_id=$2 AND status<>'delivered'`,
    [target.merchantId, target.customerId],
  );
  await scrubOutboxEvents(client, target, related);
  await scrubJobs(client, target);
}

async function scrubOutboxEvents(
  client: PoolClient,
  target: ErasureTarget,
  related: RelatedRecords,
): Promise<void> {
  const events = await client.query<{ id: string; payload: unknown }>(
    `SELECT id,payload FROM operations.outbox_events
     WHERE merchant_id=$1 AND (aggregate_id=ANY($2::uuid[]) OR payload->>'customerId'=$3)
     FOR UPDATE`,
    [target.merchantId, related.aggregateIds, target.customerId],
  );
  for (const event of events.rows) {
    await client.query('UPDATE operations.outbox_events SET payload=$2 WHERE id=$1', [
      event.id,
      scrubPersonalData(event.payload),
    ]);
  }
}

async function scrubJobs(client: PoolClient, target: ErasureTarget): Promise<void> {
  const jobs = await client.query<{ id: string; payload: unknown }>(
    `SELECT id,payload FROM operations.jobs
     WHERE merchant_id=$1 AND payload->>'customerId'=$2 FOR UPDATE`,
    [target.merchantId, target.customerId],
  );
  for (const job of jobs.rows) {
    await client.query('UPDATE operations.jobs SET payload=$2 WHERE id=$1', [
      job.id,
      scrubPersonalData(job.payload),
    ]);
  }
}

/**
 * Keeps payments, refunds, invoices and their ledger entries financially intact while removing the
 * customer profiles, free-text and provider payloads copied into them.
 */
export async function eraseFinancialRecords(
  client: PoolClient,
  target: ErasureTarget,
  related: RelatedRecords,
): Promise<void> {
  await client.query(
    `UPDATE payments.payment_intents SET customer_snapshot=$3,description=NULL,updated_at=now()
     WHERE merchant_id=$1 AND customer_id=$2`,
    [target.merchantId, target.customerId, ERASED_CUSTOMER],
  );
  await client.query(
    `UPDATE payments.invoices SET billing_snapshot=$3
     WHERE merchant_id=$1 AND customer_id=$2`,
    [target.merchantId, target.customerId, ERASED_CUSTOMER],
  );
  await client.query(
    `UPDATE payments.refunds SET customer_email=NULL
     WHERE merchant_id=$1 AND payment_intent_id=ANY($2::uuid[])`,
    [target.merchantId, related.paymentIds],
  );
  const attempts = await client.query<{ id: string; request_payload: unknown; response_payload: unknown }>(
    `SELECT id,request_payload,response_payload FROM payments.payment_attempts
     WHERE merchant_id=$1 AND payment_intent_id=ANY($2::uuid[]) FOR UPDATE`,
    [target.merchantId, related.paymentIds],
  );
  for (const attempt of attempts.rows) {
    await client.query(
      'UPDATE payments.payment_attempts SET request_payload=$2,response_payload=$3 WHERE id=$1',
      [
        attempt.id,
        scrubPersonalData(attempt.request_payload),
        attempt.response_payload === null ? null : scrubPersonalData(attempt.response_payload),
      ],
    );
  }
  const disputes = await client.query<{ id: string; evidence: unknown }>(
    `SELECT id,evidence FROM payments.disputes
     WHERE merchant_id=$1 AND payment_intent_id=ANY($2::uuid[]) FOR UPDATE`,
    [target.merchantId, related.paymentIds],
  );
  for (const dispute of disputes.rows) {
    await client.query('UPDATE payments.disputes SET evidence=$2 WHERE id=$1', [
      dispute.id,
      scrubPersonalData(dispute.evidence),
    ]);
  }
}

/** Removes the operational copies of the profile: analytics, notifications and audit metadata. */
export async function eraseOperationalRecords(
  client: PoolClient,
  target: ErasureTarget,
  related: RelatedRecords,
): Promise<void> {
  const identifiers = await customerIdentifiers(client, target);
  await client.query(
    `DELETE FROM operations.analytics_events
     WHERE merchant_id=$1 AND (customer_id=$2 OR properties->>'customerId'=$2::text
       OR email=ANY($3::text[]) OR anonymous_id=ANY($4::text[]))`,
    [
      target.merchantId,
      target.customerId,
      identifiers,
      related.aggregateIds.map((aggregateId) => `anon_${aggregateId}`),
    ],
  );
  await client.query(
    `DELETE FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2`,
    [target.merchantId, target.customerId],
  );
  await client.query(
    `DELETE FROM operations.notifications
     WHERE merchant_id=$1 AND (customer_id=$2 OR delivery_id IN (
       SELECT id FROM operations.email_deliveries WHERE merchant_id=$1 AND customer_id=$2
     ))`,
    [target.merchantId, target.customerId],
  );
  await client.query(
    `DELETE FROM operations.email_deliveries WHERE merchant_id=$1 AND customer_id=$2`,
    [target.merchantId, target.customerId],
  );
  await client.query(
    `DELETE FROM operations.dead_letters
     WHERE payload->>'customerId'=$1 OR payload->>'destination'=ANY($2::text[])`,
    [target.customerId, identifiers],
  );
  await scrubAuditLogs(client, target, related);
}

async function scrubAuditLogs(
  client: PoolClient,
  target: ErasureTarget,
  related: RelatedRecords,
): Promise<void> {
  const logs = await client.query<{ id: string; metadata: unknown }>(
    `SELECT id,metadata FROM platform.audit_logs
     WHERE merchant_id=$1 AND target_id=ANY($2::text[]) FOR UPDATE`,
    [target.merchantId, related.aggregateIds],
  );
  for (const log of logs.rows) {
    await client.query('UPDATE platform.audit_logs SET metadata=$2 WHERE id=$1', [
      log.id,
      scrubPersonalData(log.metadata),
    ]);
  }
  await client.query(
    `INSERT INTO platform.audit_logs
     (merchant_id,actor_type,target_type,target_id,action,metadata,correlation_id)
     SELECT $1,'system','customer',$2,'customer.data_erased',$4,$3
     WHERE NOT EXISTS(
       SELECT 1 FROM platform.audit_logs
       WHERE merchant_id=$1 AND target_id=$2 AND action='customer.data_erased'
     )`,
    [target.merchantId, target.customerId, target.requestId, { requestId: target.requestId }],
  );
}

/** Propagates the deletion to the payment provider profile PayFlow created for this customer. */
export async function eraseProviderRecords(client: PoolClient, target: ErasureTarget): Promise<void> {
  await client.query(
    `DELETE FROM provider_sandbox.customers
     WHERE merchant_id=$1 AND (payflow_customer_id=$2 OR id IN (
       SELECT provider_customer_id FROM customers.provider_customer_mappings
       WHERE merchant_id=$1 AND customer_id=$2
     ))`,
    [target.merchantId, target.customerId],
  );
  await client.query(
    `DELETE FROM customers.provider_customer_mappings WHERE merchant_id=$1 AND customer_id=$2`,
    [target.merchantId, target.customerId],
  );
}

/**
 * Deletes the customer profile itself. Support threads shared with other customers keep their
 * remaining participants and messages; only threads left without participants are removed.
 */
export async function eraseCustomerRecord(client: PoolClient, target: ErasureTarget): Promise<void> {
  const tickets = await client.query<{ ticket_id: string }>(
    `SELECT ticket_id FROM customers.support_participants WHERE customer_id=$1`,
    [target.customerId],
  );
  await client.query(
    `DELETE FROM customers.support_messages WHERE merchant_id=$1 AND author_id=$2`,
    [target.merchantId, target.customerId],
  );
  await client.query(
    `DELETE FROM customers.support_participants WHERE customer_id=$1`,
    [target.customerId],
  );
  for (const { ticket_id: ticketId } of tickets.rows) {
    const remaining = await client.query(
      'SELECT 1 FROM customers.support_participants WHERE ticket_id=$1 LIMIT 1',
      [ticketId],
    );
    if (remaining.rowCount) continue;
    await client.query('DELETE FROM customers.support_messages WHERE ticket_id=$1', [ticketId]);
    await client.query('DELETE FROM customers.support_tickets WHERE merchant_id=$1 AND id=$2', [
      target.merchantId,
      ticketId,
    ]);
  }
  await client.query('DELETE FROM customers.payment_method_refs WHERE merchant_id=$1 AND customer_id=$2', [
    target.merchantId,
    target.customerId,
  ]);
  await client.query('DELETE FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2', [
    target.merchantId,
    target.customerId,
  ]);
  await client.query('DELETE FROM customers.addresses WHERE merchant_id=$1 AND customer_id=$2', [
    target.merchantId,
    target.customerId,
  ]);
  await client.query('DELETE FROM customers.customers WHERE merchant_id=$1 AND id=$2', [
    target.merchantId,
    target.customerId,
  ]);
}
