{"command":"create","path":"/workspace/source/packages/privacy/src/projection-erasure.ts","file_text":"import { Redis } from 'ioredis';
import { config } from '../../config/src/index.js';
import { CUSTOMER_INDEX, searchClient } from '../../search/src/client.js';
import type { ErasureTarget } from './erasure-targets.js';

let cache: Redis | undefined;

function redis(): Redis {
  cache ??= new Redis(config().REDIS_URL);
  return cache;
}

export async function closeErasureCacheClient(): Promise<void> {
  if (!cache) return;
  const client = cache;
  cache = undefined;
  await client.quit();
}

/** Removes the customer from the searchable projection, including stale duplicate documents. */
export async function eraseSearchProjection(target: Pick<ErasureTarget, 'merchantId' | 'customerId'>): Promise<void> {
  const exists = await searchClient.indices.exists({ index: CUSTOMER_INDEX });
  if (!exists.body) return;
  await searchClient.deleteByQuery({
    index: CUSTOMER_INDEX,
    refresh: true,
    body: {
      query: {
        bool: {
          filter: [
            { term: { merchantId: target.merchantId } },
            { term: { customerId: target.customerId } },
          ],
        },
      },
    },
  });
  await searchClient.delete({
    index: CUSTOMER_INDEX,
    id: `${target.merchantId}:${target.customerId}`,
    refresh: true,
  }, { ignore: [404] });
}

/** Removes the cached customer profile and activity summary. */
export async function eraseCachedProjection(target: Pick<ErasureTarget, 'merchantId' | 'customerId'>): Promise<void> {
  const key = `merchant:${target.merchantId}:customer:${target.customerId}`;
  await redis().del(key, `${key}:activity`);
}
