{"command":"create","path":"/workspace/source/packages/privacy/src/document-erasure.ts","file_text":"import { createHash } from 'node:crypto';
import type { PoolClient } from 'pg';
import { DOCUMENT_BUCKET, objectStore } from '../../storage/src/minio.js';
import { customerIdentifiers, type ErasureTarget, type RelatedRecords } from './erasure-targets.js';
import { scrubStoredDocument } from './personal-data.js';

async function readObject(objectKey: string): Promise<string> {
  const stream = await objectStore.getObject(DOCUMENT_BUCKET, objectKey);
  const chunks: Buffer[] = [];
  for await (const chunk of stream) chunks.push(chunk as Buffer);
  return Buffer.concat(chunks).toString('utf8');
}

async function writeObject(objectKey: string, body: string): Promise<string> {
  await objectStore.putObject(DOCUMENT_BUCKET, objectKey, body, Buffer.byteLength(body), {
    'Content-Type': 'application/json',
  });
  return createHash('sha256').update(body).digest('hex');
}

function identifies(content: string, identifiers: string[]): boolean {
  return identifiers.some((identifier) => identifier.length > 0 && content.includes(identifier));
}

/**
 * Rewrites the retained financial documents without the customer profile and deletes the stored
 * artifacts that exist only to hold personal data. Document manifests are kept in step with the
 * object store so nothing points at content that no longer exists.
 */
export async function eraseStoredDocuments(
  client: PoolClient,
  target: ErasureTarget,
  related: RelatedRecords,
): Promise<void> {
  const identifiers = await customerIdentifiers(client, target);
  const retained = await client.query<{ object_key: string }>(
    `SELECT object_key FROM operations.document_manifests
     WHERE merchant_id=$1 AND (customer_id=$2
       OR metadata->>'paymentId'=ANY($3::text[]) OR metadata->>'invoiceId'=ANY($3::text[]))
       AND document_type IN ('receipt','invoice')`,
    [target.merchantId, target.customerId, related.aggregateIds],
  );
  for (const { object_key: objectKey } of retained.rows) {
    const document = JSON.parse(await readObject(objectKey)) as unknown;
    const checksum = await writeObject(objectKey, JSON.stringify(scrubStoredDocument(document)));
    await client.query(
      `UPDATE operations.document_manifests SET customer_id=NULL,checksum=$2,metadata=metadata-'customerId'
       WHERE merchant_id=$1 AND object_key=$3`,
      [target.merchantId, checksum, objectKey],
    );
  }
  await deleteIdentifyingArtifacts(client, target, identifiers, new Set(retained.rows.map((row) => row.object_key)));
}

async function deleteIdentifyingArtifacts(
  client: PoolClient,
  target: ErasureTarget,
  identifiers: string[],
  retainedKeys: Set<string>,
): Promise<void> {
  for (const objectKey of await merchantObjectKeys(target.merchantId)) {
    if (retainedKeys.has(objectKey)) continue;
    let content: string;
    try {
      content = await readObject(objectKey);
    } catch {
      continue;
    }
    if (!identifies(content, identifiers)) continue;
    await objectStore.removeObject(DOCUMENT_BUCKET, objectKey);
    await client.query(
      `DELETE FROM customers.customer_imports WHERE merchant_id=$1 AND object_key=$2`,
      [target.merchantId, objectKey],
    );
    await client.query(
      `DELETE FROM operations.document_manifests WHERE merchant_id=$1 AND object_key=$2`,
      [target.merchantId, objectKey],
    );
  }
}

async function merchantObjectKeys(merchantId: string): Promise<string[]> {
  return await new Promise<string[]>((resolve, reject) => {
    const keys: string[] = [];
    const stream = objectStore.listObjectsV2(DOCUMENT_BUCKET, `${merchantId}/`, true);
    stream.on('data', (item) => { if (item.name) keys.push(item.name); });
    stream.on('error', reject);
    stream.on('end', () => resolve(keys));
  });
}
