  return result.rows[0];
}

export async function findRequestByIdempotencyKey(
  client: PoolClient,
  merchantId: string,
  key: string,
): Promise<{ customer_id: string; request_id: string } | undefined> {
  const result = await client.query<{ customer_id: string; request_id: string }>(
    `SELECT customer_id,request_id FROM privacy.erasure_idempotency
     WHERE merchant_id=$1 AND key=$2`,
    [merchantId, key],
  );
  return result.rows[0];
}

export async function bindIdempotencyKey(
  client: PoolClient,
  merchantId: string,
  key: string,
  customerId: string,
  requestId: string,
): Promise<void> {
