    `INSERT INTO privacy.erasure_idempotency(merchant_id,key,customer_id,request_id)
     VALUES($1,$2,$3,$4) ON CONFLICT(merchant_id,key) DO NOTHING`,
    [merchantId, key, customerId, requestId],
  );
