}

/** Makes a request runnable again so a repeated call resumes work instead of starting a new one. */
export async function rearmErasureRequest(client: PoolClient, requestId: string): Promise<void> {
  await client.query(
    `UPDATE privacy.erasure_requests
     SET status='pending',available_at=now(),updated_at=now()
     WHERE id=$1 AND status='failed'`,
    [requestId],
  );
}

export async function claimErasureRequest(workerId: string, leaseSeconds = 120): Promise<ErasureRequestRow | undefined> {
  return await transaction(async (client) => {
    const result = await client.query<ErasureRequestRow>(
      `UPDATE privacy.erasure_requests
       SET status='processing',attempts=attempts+1,locked_by=$1,locked_at=now(),
           lease_expires_at=now()+($2 || ' seconds')::interval,updated_at=now()
       WHERE id=(SELECT id FROM privacy.erasure_requests
         WHERE status IN ('pending','failed') AND available_at<=now()
         ORDER BY available_at,created_at FOR UPDATE SKIP LOCKED LIMIT 1)
       RETURNING ${REQUEST_COLUMNS}`,
      [workerId, leaseSeconds],
    );
    return result.rows[0];
  });
}

export async function recoverExpiredErasureLeases(): Promise<number> {
  const result = await pool.query(
    `UPDATE privacy.erasure_requests
     SET status='failed',available_at=now(),locked_by=NULL,locked_at=NULL,lease_expires_at=NULL,
         last_error=COALESCE(last_error,'erasure_lease_expired'),updated_at=now()
     WHERE status='processing' AND lease_expires_at<now()`,
  );
  return result.rowCount ?? 0;
}

export async function completeErasureRequest(requestId: string): Promise<void> {
  await pool.query(
    `UPDATE privacy.erasure_requests
     SET status='completed',completed_at=now(),updated_at=now(),last_error=NULL,
         locked_by=NULL,locked_at=NULL,lease_expires_at=NULL
     WHERE id=$1`,
    [requestId],
  );
}

export async function failErasureRequest(
  requestId: string,
  errorCode: string,
  retryDelaySeconds: number,
): Promise<void> {
  await pool.query(
    `UPDATE privacy.erasure_requests
     SET status='failed',available_at=now()+($3 || ' seconds')::interval,last_error=$2,updated_at=now(),
         locked_by=NULL,locked_at=NULL,lease_expires_at=NULL
     WHERE id=$1`,
    [requestId, errorCode, retryDelaySeconds],
  );
}

export async function pendingSteps(requestId: string, steps: string[]): Promise<string[]> {
  const result = await pool.query<{ step: string }>(
    `SELECT step FROM privacy.erasure_request_steps
     WHERE request_id=$1 AND status='completed'`,
    [requestId],
  );
  const completed = new Set(result.rows.map((row) => row.step));
  return steps.filter((step) => !completed.has(step));
}

export async function markStepCompleted(client: PoolClient, requestId: string, step: string): Promise<void> {
  await client.query(
    `INSERT INTO privacy.erasure_request_steps(request_id,step,status,attempts,completed_at)
     VALUES($1,$2,'completed',1,now())
     ON CONFLICT(request_id,step)
     DO UPDATE SET status='completed',attempts=privacy.erasure_request_steps.attempts+1,
       completed_at=now(),last_error=NULL,updated_at=now()`,
    [requestId, step],
  );
}

export async function markStepFailed(requestId: string, step: string, errorCode: string): Promise<void> {
  await pool.query(
    `INSERT INTO privacy.erasure_request_steps(request_id,step,status,attempts,last_error)
     VALUES($1,$2,'pending',1,$3)
     ON CONFLICT(request_id,step)
     DO UPDATE SET attempts=privacy.erasure_request_steps.attempts+1,last_error=$3,updated_at=now()`,
    [requestId, step, errorCode],
  );
}
