{"command":"create","path":"/workspace/source/packages/privacy/src/erasure-runner.ts","file_text":"import { randomUUID } from 'node:crypto';
import { logger } from '../../observability/src/logger.js';
import { boundedExponentialBackoffSeconds } from '../../operations/src/retry-policy.js';
import {
  claimErasureRequest,
  completeErasureRequest,
  failErasureRequest,
  markStepFailed,
  recoverExpiredErasureLeases,
  type ErasureRequestRow,
} from './erasure-repository.js';
import { erasureTarget, remainingSteps, runErasureStep, type ErasureStep } from './erasure-workflow.js';

/** Stable, customer-free error codes so a failed request never leaks personal data. */
function errorCode(step: ErasureStep): string {
  return `erasure_step_failed:${step}`;
}

async function processRequest(request: ErasureRequestRow): Promise<void> {
  const target = erasureTarget(request);
  for (const step of await remainingSteps(request.id)) {
    try {
      await runErasureStep(step, target);
    } catch (error) {
      logger.error({ error, requestId: request.id, step }, 'erasure step failed');
      await markStepFailed(request.id, step, errorCode(step));
      await failErasureRequest(request.id, errorCode(step), boundedExponentialBackoffSeconds(request.attempts));
      return;
    }
  }
  await completeErasureRequest(request.id);
}

/** Drains every runnable request; returns the number of requests that were attempted. */
export async function runPendingErasures(workerId = `erasure-${randomUUID()}`): Promise<number> {
  let processed = 0;
  for (;;) {
    const request = await claimErasureRequest(workerId);
    if (!request) return processed;
    await processRequest(request);
    processed += 1;
  }
}

/** Runs data deletion work in the background of the service that accepts the requests. */
export async function startErasureRunner(signal: AbortSignal, intervalMs = 250): Promise<void> {
  const workerId = `erasure-worker-${randomUUID()}`;
  let lastLeaseRecovery = 0;
  while (!signal.aborted) {
    try {
      if (Date.now() - lastLeaseRecovery > 30_000) {
        await recoverExpiredErasureLeases();
        lastLeaseRecovery = Date.now();
      }
      const processed = await runPendingErasures(workerId);
      if (processed === 0) await new Promise((resolve) => setTimeout(resolve, intervalMs));
    } catch (error) {
      logger.error({ error }, 'erasure runner iteration failed');
      await new Promise((resolve) => setTimeout(resolve, intervalMs));
    }
  }
}
