} from './erasure-repository.js';

async function customerExists(client: PoolClient, merchantId: string, customerId: string): Promise<boolean> {
  const result = await client.query(
    `SELECT 1 FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
    [merchantId, customerId],
  );
  return Boolean(result.rowCount);
}

async function recordAudit(client: PoolClient, merchantId: string, customerId: string, requestId: string): Promise<void> {
  await client.query(
    `INSERT INTO platform.audit_logs
     (merchant_id,actor_type,target_type,target_id,action,metadata,correlation_id)
     VALUES($1,'api_key','customer',$2,'customer.erasure_requested',$3,$4)`,
    [merchantId, customerId, { requestId }, requestId],
  );
}

/**
 * Accepts a data deletion request. Repeating the call converges on the single request that owns the
 * customer: an unfinished request is made runnable again instead of starting a second workflow.
 */
export async function requestCustomerErasure(
  merchantId: string,
  customerId: string,
  idempotencyKey: string,
): Promise<ErasureRequestView> {
  return await transaction(async (client) => {
    await advisoryLock(client, `privacy-erasure:${merchantId}:${customerId}`);
    const bound = await findRequestByIdempotencyKey(client, merchantId, idempotencyKey);
    if (bound && bound.customer_id !== customerId) {
      throw Object.assign(new Error('idempotency_key_reused'), { statusCode: 409 });
    }
    const existing = await findErasureRequestForCustomer(client, merchantId, customerId);
    if (existing) {
      await bindIdempotencyKey(client, merchantId, idempotencyKey, customerId, existing.id);
      await rearmErasureRequest(client, existing.id);
      return toErasureRequestView(existing);
    }
    if (!await customerExists(client, merchantId, customerId)) {
      throw Object.assign(new Error('customer_not_found'), { statusCode: 404 });
    }
    const created = await insertErasureRequest(client, merchantId, customerId);
    await bindIdempotencyKey(client, merchantId, idempotencyKey, customerId, created.id);
    await recordAudit(client, merchantId, customerId, created.id);
    return toErasureRequestView(created);
  });
}

export async function getCustomerErasureRequest(
  merchantId: string,
  requestId: string,
): Promise<ErasureRequestView | undefined> {
  const request = await findErasureRequest(merchantId, requestId);
  return request ? toErasureRequestView(request) : undefined;
}
