import { contactAddresses, relatedRecords, type ErasureTarget, type RelatedRecords } from './erasure-targets.js';
import { eraseCachedProjection, eraseSearchProjection } from './projection-erasure.js';

/**
 * Ordered so that identity-dependent work runs while the customer profile still exists, and the
