  'operational_records',
  'stored_documents',
  'provider_records',
  'customer_record',
  'confirmation',
] as const;

export type ErasureStep = typeof ERASURE_STEPS[number];

type StepHandler = (client: PoolClient, target: ErasureTarget, related: RelatedRecords) => Promise<void>;

const STEP_HANDLERS: Record<ErasureStep, StepHandler> = {
  quarantine: quarantineCustomer,
  email_provider: async (client, target, related) => {
    for (const address of await contactAddresses(client, target, related.paymentIds)) {
      await deleteMailpitMessagesForRecipient(address);
    }
  },
  projections: async (_client, target) => {
    await eraseSearchProjection(target);
    await eraseCachedProjection(target);
  },
  financial_records: eraseFinancialRecords,
  operational_records: eraseOperationalRecords,
  stored_documents: eraseStoredDocuments,
  provider_records: async (client, target) => await eraseProviderRecords(client, target),
  customer_record: async (client, target) => await eraseCustomerRecord(client, target),
  confirmation: async (client, target, related) => {
    await eraseSearchProjection(target);
    await eraseCachedProjection(target);
    await assertNoResidualPersonalData(client, target, related);
  },
};

export function erasureTarget(request: ErasureRequestRow): ErasureTarget {
  return { merchantId: request.merchant_id, customerId: request.customer_id, requestId: request.id };
}

export async function remainingSteps(requestId: string): Promise<ErasureStep[]> {
  return await pendingSteps(requestId, [...ERASURE_STEPS]) as ErasureStep[];
}

/**
 * Runs one step and records it as finished in the same transaction, so a step either has no effect
 * or is never attempted again.
 */
export async function runErasureStep(step: ErasureStep, target: ErasureTarget): Promise<void> {
  await transaction(async (client) => {
    await advisoryLock(client, `privacy-erasure:${target.merchantId}:${target.customerId}`);
    const related = await relatedRecords(client, target);
    await STEP_HANDLERS[step](client, target, related);
    await markStepCompleted(client, target.requestId, step);
  });
}
